template<typename T>
void write(const std::string& path, const T& value) {
  std::ofstream file(path, std::ios::binary);
  file.write(reinterpret_cast<const char*>(&value), static_cast<std::streamsize>(sizeof(T)));
  require(static_cast<bool>(file), "write failed");
}
std::vector<char> read(const std::string& path) {
  std::ifstream file(path, std::ios::binary);
  require(static_cast<bool>(file), "read failed");
  return { std::istreambuf_iterator<char>(file), std::istreambuf_iterator<char>() };
}
